(7617803, 1233381, 67145, '<td valign="top">so incredibly appealing this image .. loving the bnw .. loving the minimalism .. love the reflection .. and the diagonal shadow .. :)</td>', 'so incredibly appealing this image .. loving the bnw .. loving the minimalism .. love the reflection .. and the diagonal shadow .. :)', '2019-03-07 15:08:28.000000', NULL, 1),
(7617804, 1233102, 67145, '<td valign="top">loving the drama .. and the stunning blue shadows on the snow .. the sun''s rays just lift this into the realms of absolutely GORGEOUS .. the sky is wonderful .. very very appealing image .. :)</td>', 'loving the drama .. and the stunning blue shadows on the snow .. the sun''s rays just lift this into the realms of absolutely GORGEOUS .. the sky is wonderful .. very very appealing image .. :)', '2019-03-07 15:09:57.000000', NULL, 1),
(7617807, 1233391, 67145, '<td valign="top">oh my goodness .. !!! .. <br/>at first its not immediately obvious that they are clouds .. they could almost be waves .. then of course the reality hits .. <br/>incredible image .. mainly because of the location .. and thats what its all about sometimes .. location location .. and being there ... <br/>i love how it feels like i''m on top of the world and how the land drops away .. i''m getting vertigo .. this is wonderful .. especially good in bnw . :)</td>', 'oh my goodness .. !!! .. at first its not immediately obvious that they are clouds .. they could almost be waves .. then of course the reality hits .. incredible image .. mainly because of the location .. and thats what its all about sometimes .. location location .. and being there ... i love how it feels like i''m on top of the world and how the land drops away .. i''m getting vertigo .. this is wonderful .. especially good in bnw . :)', '2019-03-07 15:14:39.000000', NULL, 1),
(7617814, 1233417, 59740, '<td valign="top">Does not exhibit a fully range of tones even in the bird''s face. Good idea but the long black bar crossing through the bird is distracting.</td>', 'Does not exhibit a fully range of tones even in the bird''s face. Good idea but the long black bar crossing through the bird is distracting.', '2019-03-07 17:12:59.000000', NULL, 1),
